#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto &v : a) cin >> v;
    // Each segment's maximum is owned by one position: strictly greater on the left,
    // greater-or-equal on the right.
    vector<int> left(n, -1), right(n, n), st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && a[st.back()] <= a[i]) st.pop_back();
        if (!st.empty()) left[i] = st.back();
        st.push_back(i);
    }
    st.clear();
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() && a[st.back()] < a[i]) st.pop_back();
        if (!st.empty()) right[i] = st.back();
        st.push_back(i);
    }
    const long long MOD = 1000000007;
    long long answer = 0;
    for (int i = 0; i < n; i++) {
        long long l = i - left[i], r = right[i] - i;
        // Total length of all owned segments: l * r * (l + r) / 2 (fits in 64 bits).
        long long lengths = l * r * (l + r) / 2 % MOD;
        answer = (answer + a[i] % MOD * lengths) % MOD;
    }
    cout << answer << "\n";
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Each segment's maximum is owned by one position: strictly greater on the left,
        // greater-or-equal on the right.
        int[] left = new int[n], right = new int[n], st = new int[n];
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (top > 0 && a[st[top - 1]] <= a[i]) top--;
            left[i] = top > 0 ? st[top - 1] : -1;
            st[top++] = i;
        }
        top = 0;
        for (int i = n - 1; i >= 0; i--) {
            while (top > 0 && a[st[top - 1]] < a[i]) top--;
            right[i] = top > 0 ? st[top - 1] : n;
            st[top++] = i;
        }
        final long MOD = 1000000007L;
        long answer = 0;
        for (int i = 0; i < n; i++) {
            long l = i - left[i], r = right[i] - i;
            // Total length of all owned segments: l * r * (l + r) / 2 (fits in 64 bits).
            long lengths = l * r * (l + r) / 2 % MOD;
            answer = (answer + a[i] % MOD * lengths) % MOD;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Each segment's maximum is owned by one position: strictly greater on the left,
	// greater-or-equal on the right.
	left, right, st := make([]int, n), make([]int, n), []int{}
	for i := 0; i < n; i++ {
		for len(st) > 0 && a[st[len(st)-1]] <= a[i] {
			st = st[:len(st)-1]
		}
		left[i] = -1
		if len(st) > 0 {
			left[i] = st[len(st)-1]
		}
		st = append(st, i)
	}
	st = st[:0]
	for i := n - 1; i >= 0; i-- {
		for len(st) > 0 && a[st[len(st)-1]] < a[i] {
			st = st[:len(st)-1]
		}
		right[i] = n
		if len(st) > 0 {
			right[i] = st[len(st)-1]
		}
		st = append(st, i)
	}
	const mod = 1000000007
	answer := int64(0)
	for i := 0; i < n; i++ {
		l, r := int64(i-left[i]), int64(right[i]-i)
		// Total length of all owned segments: l * r * (l + r) / 2 (fits in 64 bits).
		lengths := l * r * (l + r) / 2 % mod
		answer = (answer + a[i]%mod*lengths) % mod
	}
	fmt.Println(answer)
}
